WITH latest_match AS (SELECT s.*, x.order_item_quantity FROM products s LEFT JOIN LATERAL (SELECT c.quantity AS order_item_quantity FROM order_items c WHERE c.product_id = s.id ORDER BY c.quantity DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT DATE_TRUNC('QUARTER', launch_date) AS quarter_start, DATE_TRUNC('MONTH', launch_date) AS activity_month, APPROX_PERCENTILE(order_item_quantity, ARRAY(0.25, 0.5, 0.75)) AS order_item_quantity_quartiles, SORT_ARRAY(COLLECT_SET(category)) AS category_list FROM latest_match GROUP BY GROUPING SETS ((DATE_TRUNC('QUARTER', launch_date), DATE_TRUNC('MONTH', launch_date)), (DATE_TRUNC('QUARTER', launch_date)), ()) ORDER BY activity_month DESC NULLS LAST;
